const email = String($json.email || "").trim();
const appointment_date = String($json.appointment_date || "").trim();
const doctor_name = String($json.doctor_name || "").trim();

if (!email) {
  return [
    {
      json: {
        valid: false,
        error: "Email is required to fetch appointment details."
      }
    }
  ];
}

return [
  {
    json: {
      valid: true,
      email,
      appointment_date,
      doctor_name
    }
  }
];

const appointments = items
  .map(item => item.json)
  .filter(appt => appt.appointment_id);

if (appointments.length === 0) {
  return [
    {
      json: {
        found: false,
        total_appointments: 0,
        appointments: [],
        response_message: "No active appointments found for this email."
      }
    }
  ];
}

const formattedAppointments = appointments.map(appt => ({
  appointment_id: appt.appointment_id,
  patient_id: appt.patient_id,
  patient_name: appt.patient_name,
  email: appt.email,
  phone: appt.phone || "",

  doctor_id: appt.doctor_id,
  doctor_name: appt.doctor_name,
  department: appt.department,
  specialization: appt.specialization || "",
  consultation_duration: appt.consultation_duration,

  appointment_date: appt.appointment_date,
  appointment_start: appt.appointment_start,
  appointment_end: appt.appointment_end,
  appointment_time: appt.appointment_time,
  appointment_end_time: appt.appointment_end_time,

  appointment_type: appt.appointment_type,
  reason: appt.reason,
  triage_level: appt.triage_level,
  status: appt.status,
  booking_source: appt.booking_source,
  created_at: appt.created_at
}));

const latest = formattedAppointments[0];

return [
  {
    json: {
      found: true,
      total_appointments: formattedAppointments.length,
      appointments: formattedAppointments,
      latest_appointment: latest,

      ...latest,

      response_message: `${formattedAppointments.length} active appointment(s) found.`
    }
  }
];
